/**
 * 🛑 SISTEMA DE RATE LIMIT PARA RETRIES
 * Evita loop infinito de retries em grupos grandes
 *
 * 🚀 OTIMIZADO para 20+ grupos × 1024 membros:
 * - Limites mais rigorosos para evitar sobrecarga
 * - Cooldown maior quando limite é atingido
 */
const RETRY_LIMITER = {
    // Máximo de retries por grupo em um período (reduzido de 3 para 2)
    MAX_RETRIES_PER_GROUP: 2,
    // Período de reset (60 segundos)
    RESET_PERIOD_MS: 60 * 1000,
    // Cooldown quando limite é atingido (8 minutos - aumentado de 5)
    COOLDOWN_MS: 8 * 60 * 1000,
    // Bloquear retries para grupos com mais de X dispositivos (reduzido de 200 para 150)
    MAX_GROUP_SIZE_FOR_RETRY: 150,
    // Mapa de contagem: groupJid -> { count, resetAt, blockedUntil }
    groupRetries: new Map(),
    // Grupos grandes que devem ser ignorados (cache temporário)
    largeGroups: new Set()
};
/**
 * Marca um grupo como grande (muitos dispositivos)
 */
function markGroupAsLarge(groupJid) {
    RETRY_LIMITER.largeGroups.add(groupJid);
    // Limpar após 10 minutos
    setTimeout(() => {
        RETRY_LIMITER.largeGroups.delete(groupJid);
    }, 10 * 60 * 1000);
}
/**
 * Verifica se pode processar retry para um grupo
 */
function canProcessRetry(groupJid, logger) {
    // Se grupo já foi marcado como grande, ignorar silenciosamente
    if (RETRY_LIMITER.largeGroups.has(groupJid)) {
        return false;
    }
    const now = Date.now();
    let data = RETRY_LIMITER.groupRetries.get(groupJid);
    // Se não existe, criar
    if (!data) {
        data = { count: 0, resetAt: now + RETRY_LIMITER.RESET_PERIOD_MS, blockedUntil: 0 };
        RETRY_LIMITER.groupRetries.set(groupJid, data);
    }
    // Se está em cooldown, ignorar silenciosamente
    if (data.blockedUntil > now) {
        return false;
    }
    // Se passou o período de reset, zerar contagem
    if (now > data.resetAt) {
        data.count = 0;
        data.resetAt = now + RETRY_LIMITER.RESET_PERIOD_MS;
    }
    // Incrementar contagem
    data.count++;
    // Se excedeu limite, bloquear
    if (data.count > RETRY_LIMITER.MAX_RETRIES_PER_GROUP) {
        data.blockedUntil = now + RETRY_LIMITER.COOLDOWN_MS;
        logger.warn({
            group: groupJid,
            retryCount: data.count,
            cooldownMinutes: RETRY_LIMITER.COOLDOWN_MS / 60000
        }, '🛑 Grupo com muitos retries - bloqueando por 5 minutos');
        return false;
    }
    return true;
}
